package com.avizero.avidrive.api;
import com.avizero.avidrive.domain.*; import com.avizero.avidrive.repository.*; import com.avizero.avidrive.security.AuthUser; import java.util.Map; import org.springframework.http.ResponseEntity; import org.springframework.security.core.Authentication; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/profile") public class ProfileController {private final UserRepository users;private final PasswordEncoder encoder;private final AuditLogRepository audit;public ProfileController(UserRepository u,PasswordEncoder e,AuditLogRepository a){users=u;encoder=e;audit=a;}
@GetMapping public ResponseEntity<?> profile(Authentication a){return ResponseEntity.ok(view(current(a)));}
@PatchMapping("/password") public ResponseEntity<?> password(@RequestBody PasswordRequest r,Authentication a){User u=current(a);if(r.current_password()==null||!encoder.matches(r.current_password(),u.passwordHash))return error(401,"Неверный текущий пароль");if(r.new_password()==null||r.new_password().length()<8)return error(400,"Новый пароль должен содержать минимум 8 символов");u.passwordHash=encoder.encode(r.new_password());users.save(u);AuditLog l=new AuditLog();l.actorId=u.id;l.action="PASSWORD_CHANGED";l.targetType="USER";l.targetId=u.id;l.details="Пароль изменён";audit.save(l);return ResponseEntity.ok(Map.of("message","Пароль изменён"));}
private User current(Authentication a){return users.findById(((AuthUser)a.getPrincipal()).id()).orElseThrow();}private Map<String,Object> view(User u){return Map.of("username",u.username,"role",u.role,"quota_mb",u.quotaMb==null?0:u.quotaMb,"used_bytes",u.usedBytes==null?0:u.usedBytes);}private ResponseEntity<Map<String,String>> error(int s,String m){return ResponseEntity.status(s).body(Map.of("message",m));}public record PasswordRequest(String current_password,String new_password){}
}
